var target = "127.0.0.1";
var openPorts = [135, 445];

// Function to analyze network scan results
function analyzeNetworkScan(target, openPorts) {
    // Implement anomaly analysis logic here
    var anomalies = [];

    if (openPorts.includes(135)) { 
        anomalies.push("Port 135 is active and connected to the target.");
    }
    if (openPorts.includes(445)) { 
        anomalies.push("Port 445 is active and connected to the target.");
    }

    return anomalies;
}

// Function to display the results
function displayAnomalies(anomalies) {
    var anomaliesHTML = "";
    for (var i = 0; i < anomalies.length; i++) {
        var anomalyHtml = "Anomaly: " + (i+1) + ". " + anomalies[i];
        anomaliesHTML += `<div>${anomalyHtml}</div>`;
    }
    document.getElementById("anomalies").innerHTML = anomaliesHTML;
}

// Analyze the network scan results
analyzeNetworkScan(target, openPorts);

// Display the results in a table format
document.getElementById("anomalies").innerHTML = displayAnomalies(anomalies);
```

